#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int LLVMFuzzerTestOneInput(const uint8_t*, size_t);

static uint32_t rng_state = 0x12345678;
static uint32_t rnd(void){
    rng_state ^= rng_state << 13;
    rng_state ^= rng_state >> 17;
    rng_state ^= rng_state << 5;
    return rng_state;
}

int main(int argc, char** argv){
    (void)argc;
    const unsigned flags[] = {
        0x100,                              /* TABLES */
        0x1ff,                              /* many common */
        0x80000|0x100,                      /* ADMONITIONS|TABLES */
        0x100|0x200|0x800|0x4000|0x10000|0x20000|0x40000,
        0x8ff,                              /* PERMISSIVEAUTOLINKS|...|TABLES */
        0xffffffffu,
    };
    size_t nflags = sizeof(flags)/sizeof(flags[0]);

    /* Seed corpus: markdown snippets (without header) */
    const char* seeds[] = {
        "a|b\n-|-\n", "a|b\n---|---\n", "a|b\n| --- | --- |\n",
        "|a|b|\n|:-:|:-:|\n", "a|b\n|:---|---:|\n", "a|b\n-:|:-\n",
        "a\n|---\n", "|a|b|\n|--|--|\n", "a|b|c\n|---|---|---|\n",
        "> a|b\n> |---|\n", "- a|b\n  |---|\n", "a|b\n||--|\n",
        "a|b\n|:-:||\n", "a|b\n:-:|:-:|\n", "[a](b)|c\n---|---\n",
        "a|b\n| |\n", "|||\n-|-|-\n", "a|b\n| - | - \n",
    };
    size_t nseeds = sizeof(seeds)/sizeof(seeds[0]);

    size_t seed = (argc > 1) ? (size_t)strtoul(argv[1], NULL, 10) : 0;
    rng_state ^= (uint32_t)seed * 2654435761u;

    /* Build initial corpus: random mutations of seeds, with flags header. */
    uint8_t* corpus[256];
    size_t corpus_len[256];
    size_t ncorpus = 0;
    for(size_t i = 0; i < nseeds && ncorpus < 200; i++) {
        size_t slen = strlen(seeds[i]);
        for(int rep = 0; rep < 8 && ncorpus < 200; rep++) {
            size_t len = slen + (rnd() % 16);
            uint8_t* buf = malloc(len + 8);
            size_t j;
            for(j = 0; j < len; j++) {
                char c = seeds[i][j % slen];
                if((rnd() % 100) < 15)
                    c = (char)(rnd() % 256);
                buf[8 + j] = (uint8_t)c;
            }
            /* random truncation / extension */
            if((rnd() % 100) < 30) len = rnd() % (slen + 8);
            corpus[ncorpus] = buf;
            corpus_len[ncorpus] = len;
            ncorpus++;
        }
    }
    /* add pure random */
    for(size_t i = 0; i < 50 && ncorpus < 256; i++) {
        size_t len = rnd() % 64;
        uint8_t* buf = malloc(len + 8);
        for(size_t j = 0; j < len; j++) buf[8 + j] = (uint8_t)(rnd() % 256);
        corpus[ncorpus] = buf;
        corpus_len[ncorpus] = len;
        ncorpus++;
    }

    unsigned long long iters = 0;
    while(1) {
        size_t ci = rnd() % ncorpus;
        size_t len = corpus_len[ci];
        uint8_t* buf = corpus[ci];
        /* random header flags */
        uint32_t pf = flags[rnd() % nflags];
        uint32_t rf = (rnd() % 4) ? 0 : (uint32_t)(rnd());
        memcpy(buf, &pf, 4);
        memcpy(buf+4, &rf, 4);

        /* mutate */
        int nmut = 1 + (rnd() % 4);
        for(int m = 0; m < nmut; m++) {
            size_t pos = rnd() % (len + 8);
            switch(rnd() % 5) {
                case 0: buf[pos] ^= (uint8_t)(1u << (rnd() % 8)); break;
                case 1: buf[pos] = (uint8_t)(rnd() % 256); break;
                case 2: if(len + 8 < 4096) { memmove(buf+pos+1, buf+pos, len+8-pos); len++; } break;
                case 3: if(len > 0) { memmove(buf+pos, buf+pos+1, len+8-pos-1); len--; } break;
                case 4: if(len > 0 && pos < len+8) { size_t blk = 1 + rnd()%16; size_t src = rnd() % (len+8); for(size_t k=0; k<blk && pos+k < len+8 && src+k < len+8; k++) buf[pos+k] = buf[src+k]; } break;
            }
        }
        if(len + 8 > 4096) len = 4096 - 8;
        corpus_len[ci] = len;

        LLVMFuzzerTestOneInput(buf, len + 8);
        iters++;
        if((iters & 0xFFFF) == 0) {
            fprintf(stderr, "iters=%llu\n", iters);
        }
    }
    return 0;
}

